import React from 'react'

function BankProcessingSection({ application }) {

    const banks = application?.bank_processing || []

    return (
        <div className="card bg-base-100 border border-base-300 shadow-sm">

            <div className="card-body">

                {/* -------------------------------------------------
                    HEADER
                -------------------------------------------------- */}

                <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">

                    <div>

                        <h2 className="text-lg font-semibold">
                            Bank Processing
                        </h2>

                        <p className="text-sm text-base-content/50 mt-1">
                            Manage bank assignments and workflow
                        </p>

                    </div>


                    {/* ACTIONS */}

                    <div className="flex items-center gap-2">

                        <button
                            type="button"
                            className="btn btn-sm btn-outline"
                        >
                            ↻ Live Updates
                        </button>

                        <button
                            type="button"
                            className="btn btn-sm btn-outline"
                        >
                            ↻ Refresh
                        </button>

                    </div>

                </div>


                {/* -------------------------------------------------
                    ASSIGN BANK
                -------------------------------------------------- */}

                <div className="flex justify-end mt-2">

                    <button
                        type="button"
                        className="btn btn-sm"
                        style={{
                            backgroundColor: 'rgb(143, 212, 0)',
                            borderColor: 'rgb(143, 212, 0)',
                            color: '#111827',
                        }}
                    >
                        + Assign Bank
                    </button>

                </div>


                {/* -------------------------------------------------
                    BANK LIST
                -------------------------------------------------- */}

                <div className="mt-5">

                    {banks.length === 0 ? (

                        <div className="border border-base-300 rounded-xl p-8 text-center">

                            <p className="text-sm text-base-content/50">
                                No banks assigned to this application yet
                            </p>

                            <button
                                type="button"
                                className="btn btn-sm mt-4"
                            >
                                + Assign First Bank
                            </button>

                        </div>

                    ) : (

                        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">

                            {banks.map((bank, index) => (

                                <BankCard
                                    key={bank.id || index}
                                    bank={bank}
                                />

                            ))}

                        </div>

                    )}

                </div>

            </div>

        </div>
    )
}


/* ================================================================
   BANK CARD
================================================================ */

function BankCard({ bank }) {

    const status = bank?.status || 'Assigned'

    return (

        <div className="border border-base-300 rounded-xl p-4 bg-base-100">

            {/* -------------------------------------------------
                BANK HEADER
            -------------------------------------------------- */}

            <div className="flex items-start justify-between">

                <div className="flex items-center gap-3">

                    {/* Bank Avatar */}

                    <div
                        className="w-8 h-8 rounded-full flex items-center justify-center text-xs font-semibold"
                        style={{
                            backgroundColor:
                                'rgb(143, 212, 0)',
                            color: '#ffffff',
                        }}
                    >
                        {bank?.bank_name?.charAt(0)?.toUpperCase() || 'B'}
                    </div>


                    <div>

                        <p className="font-semibold text-sm">
                            {bank?.bank_name || '-'}
                        </p>

                        <p className="text-xs text-base-content/50 mt-0.5">
                            DSA: {bank?.dsa || '-'}
                        </p>

                    </div>

                </div>


                {/* Delete */}

                <button
                    type="button"
                    className="btn btn-ghost btn-xs text-error"
                    title="Remove bank"
                >
                    🗑
                </button>

            </div>


            {/* -------------------------------------------------
                STEP
            -------------------------------------------------- */}

            <div className="flex justify-between items-center mt-4">

                <span
                    className="badge badge-sm"
                    style={{
                        backgroundColor:
                            status === 'Disbursed'
                                ? 'rgba(143, 212, 0, 0.12)'
                                : 'rgba(59, 130, 246, 0.10)',
                        color:
                            status === 'Disbursed'
                                ? 'rgb(100, 160, 0)'
                                : 'rgb(37, 99, 235)',
                    }}
                >
                    {status}
                </span>


                <span className="text-xs text-base-content/50">
                    Step {bank?.current_step || 0}/{bank?.total_steps || 3}
                </span>

            </div>


            {/* -------------------------------------------------
                AMOUNTS
            -------------------------------------------------- */}

            <div className="grid grid-cols-2 gap-2 mt-4">

                <AmountBox
                    label="Offered"
                    amount={bank?.offered_amount}
                />

                <AmountBox
                    label="Disbursed"
                    amount={bank?.disbursed_amount}
                />

            </div>


            {/* -------------------------------------------------
                TIMELINE
            -------------------------------------------------- */}

            <div className="mt-5">

                <p className="text-sm font-semibold mb-4">
                    Timeline
                </p>


                <div className="grid grid-cols-4 gap-1">

                    <TimelineItem
                        label="Assigned"
                        date={bank?.assigned_at}
                        active
                    />

                    <TimelineItem
                        label="Login"
                        date={bank?.login_at}
                        active={Boolean(bank?.login_at)}
                    />

                    <TimelineItem
                        label="Sanction"
                        date={bank?.sanction_at}
                        active={Boolean(bank?.sanction_at)}
                    />

                    <TimelineItem
                        label="Disburse"
                        date={bank?.disbursement_at}
                        active={Boolean(bank?.disbursement_at)}
                    />

                </div>

            </div>

        </div>
    )
}


/* ================================================================
   AMOUNT BOX
================================================================ */

function AmountBox({ label, amount }) {

    return (

        <div className="border border-base-300 rounded-lg px-3 py-2">

            <p className="text-[11px] text-base-content/50">
                {label}
            </p>

            <p className="text-sm font-semibold mt-1">
                {formatAmount(amount)}
            </p>

        </div>
    )
}


/* ================================================================
   TIMELINE ITEM
================================================================ */

function TimelineItem({
    label,
    date,
    active,
}) {

    return (

        <div className="text-center">

            <div
                className={`
                    mx-auto
                    w-5
                    h-5
                    rounded-full
                    flex
                    items-center
                    justify-center
                    text-[10px]
                    ${
                        active
                            ? 'bg-success text-white'
                            : 'bg-base-300 text-base-content/40'
                    }
                `}
            >
                {active ? '✓' : ''}
            </div>


            <p className="text-[10px] text-base-content/50 mt-1">
                {label}
            </p>


            <p className="text-[10px] font-medium mt-1">
                {formatDate(date)}
            </p>

        </div>
    )
}


/* ================================================================
   HELPERS
================================================================ */

function formatAmount(amount) {

    if (
        amount === null ||
        amount === undefined ||
        amount === ''
    ) {
        return '-'
    }

    return `₹ ${Number(amount).toLocaleString('en-IN')}`
}


function formatDate(date) {

    if (!date) {
        return '-'
    }

    return new Date(date).toLocaleDateString(
        'en-IN',
        {
            day: '2-digit',
            month: 'short',
        }
    )
}


export default BankProcessingSection
